            "filter": build_filter(request.left_dimensions or {}),
            "interval": {
                "startTime": request.start_time.isoformat(),
                "endTime": request.end_time.isoformat(),
            },
            "view": "FULL",
        }
    )
    right = client.list_time_series(
        {
            "filter": build_filter(request.right_dimensions or {}),
            "interval": {
                "startTime": request.start_time.isoformat(),
                "endTime": request.end_time.isoformat(),
