        tables.append(
            {
                "row_count": getattr(table, "row_count", None),
                "column_count": getattr(table, "column_count", None),
                "cells": cells,
            }
        )
    return DocumentResponse(
        tables=tables, text=normalize_text(getattr(result, "content", "")), raw=result
    )

