import os
from typing import List, Dict, Any

from openai import OpenAI


class SemanticSearchEmbedder:
    def __init__(
        self,
        api_key: str | None = None,
        model: str = "text-embedding-3-small",
    ) -> None:
        self.client = OpenAI(api_key=api_key or os.environ["OPENAI_API_KEY"])
        self.model = model

    def _embed_texts(self, texts: List[str]) -> List[List[float]]:
        if not texts:
            return []
        response = self.client.embeddings.create(
            model=self.model,
            input=texts,
        )
        return [item.embedding for item in response.data]

    def embed_query_and_documents(
        self,
        query: str,
        documents: List[str],
    ) -> Dict[str, Any]:
        if not isinstance(query, str) or not query.strip():
            raise ValueError("query must be a non-empty string")
        if not isinstance(documents, list):
            raise ValueError("documents must be a list of strings")
        if any(not isinstance(doc, str) or not doc.strip() for doc in documents):
            raise ValueError("each document must be a non-empty string")

        query_embedding = self._embed_texts([query])[0]
        document_embeddings = self._embed_texts(documents)

        return {
            "provider": "openai",
            "model": self.model,
            "query": {
                "text": query,
                "embedding": query_embedding,
            },
            "documents": [
                {"text": doc, "embedding": emb}
                for doc, emb in zip(documents, document_embeddings)
            ],
        }

