        raise ValueError('No expense documents found')

    document = response['ExpenseDocuments'][0]
    if document['DocumentMetadata']['Confidence'] < 90.0:
        raise ValueError('Low confidence score')

    fields = document['LineItems'][0]['ExpenseFields']
    required_fields = ['Total', 'InvoiceTotal']
