        if fields[next(i for i, ef in enumerate(fields) if ef['Type']['Text'] == field)]['Value']['Confidence'] < 80.0:
            raise ValueError(f'Low confidence score for field: {field}')

    return {
        'total': fields[next(i for i, ef in enumerate(fields) if ef['Type']['Text'] == 'Total')]['Value']['Text'],
        'invoice_total': fields[next(i for i, ef in enumerate(fields) if ef['Type']['Text'] == 'InvoiceTotal')]['Value']['Text']
    }
