from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential


def extract_layout_and_ocr(file_path: str, endpoint: str, api_key: str) -> Dict[str, Any]:
    client = DocumentAnalysisClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(api_key)
    )

    with open(file_path, "rb") as document:
        poller = client.begin_analyze_document(model_id="prebuilt-layout", document=document)
        result = poller.result()

    layout_data: Dict[str, Any] = {
        "paragraphs": [],
        "lines": [],
        "tables": []
    }

    def _extract_bbox(element) -> List[float]:
        if hasattr(element, "bounding_regions") and element.bounding_regions:
            return element.bounding_regions[0].polygon
        return getattr(element, "polygon", [])

    for page in result.pages:
        if page.lines:
            for line in page.lines:
                layout_data["lines"].append({
                    "content": line.content,
                    "bounding_polygon": _extract_bbox(line)
                })

        if page.paragraphs:
            for paragraph in page.paragraphs:
                layout_data["paragraphs"].append({
                    "content": paragraph.content,
                    "bounding_polygon": _extract_bbox(paragraph),
                    "role": paragraph.role
                })

    for table in result.tables:
        cells = []
        for cell in table.cells:
            cells.append({
                "row_index": cell.row_index,
                "column_index": cell.column_index,
                "content": cell.content,
                "bounding_polygon": _extract_bbox(cell),
                "is_header": cell.is_header
            })

        table_bbox = _extract_bbox(table) if table.bounding_regions else []

        layout_data["tables"].append({
            "row_count": table.row_count,
            "column_count": table.column_count,
            "bounding_polygon": table_bbox,
            "cells": cells
        })

    return layout_data

