import os
import io
from typing import BinaryIO, Optional, Union

import boto3
from botocore.exceptions import BotoCoreError, ClientError


class S3UploadError(Exception):
    pass


def upload_to_s3(
    bucket_name: str,
    object_key: str,
    source: Union[str, bytes, bytearray, BinaryIO],
    content_type: Optional[str] = None,
    region_name: Optional[str] = None,
) -> str:
    session = boto3.session.Session(region_name=region_name)
    s3 = session.client("s3")

    extra_args = {}
    if content_type:
        extra_args["ContentType"] = content_type

    try:
        if isinstance(source, str):
            with open(source, "rb") as f:
                s3.upload_fileobj(f, bucket_name, object_key, ExtraArgs=extra_args or None)
        elif isinstance(source, (bytes, bytearray)):
            with io.BytesIO(source) as bio:
                s3.upload_fileobj(bio, bucket_name, object_key, ExtraArgs=extra_args or None)
        elif hasattr(source, "read"):
            s3.upload_fileobj(source, bucket_name, object_key, ExtraArgs=extra_args or None)
        else:
            raise TypeError("source must be a file path, bytes, bytearray, or binary file-like object")
    except (OSError, BotoCoreError, ClientError) as e:
        raise S3UploadError(f"Failed to upload to Amazon S3 bucket '{bucket_name}' with key '{object_key}': {e}") from e

    resolved_region = region_name or session.region_name or os.getenv("AWS_REGION") or "us-east-1"
    return f"s3://{bucket_name}/{object_key}"

