import os
from azure.ai.contentsafety import TextAnalysisClient
from azure.core.credentials import AzureKeyCredential

def analyze_text_safety(text: str) -> dict:
    endpoint = os.environ["AZURE_CONTENT_SAFETY_ENDPOINT"]
    key = os.environ["AZURE_CONTENT_SAFETY_KEY"]

    client = TextAnalysisClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    categories = ["Hate", "SelfHarm", "Sexual", "Violence"]

    response = client.analyze_text(text=text, categories=categories)

    results = {}
    overall_flagged = False
    for category_result in response.categories_analysis:
        severity = category_result.severity
        is_flagged = severity > 0
        results[str(category_result.category)] = {
            "severity": severity,
            "flagged": is_flagged
        }
        if is_flagged:
            overall_flagged = True

    return {
        "flagged": overall_flagged,
        "categories": results
    }

