import os
import boto3
from botocore.exceptions import ClientError

def conditional_update(payload, config=None):
    config = config or {}
    dynamodb = boto3.resource('dynamodb', region_name=config.get('aws_region', os.environ.get('AWS_REGION')))
    table = dynamodb.Table(payload['table_name'])

    def execute_update():
        try:
            # DynamoDB's ConditionExpression is a provider-specific feature for conditional updates.
            # If the condition is not met, AWS returns a ConditionalCheckFailedException.
            # This is a common pattern for optimistic locking, using a version attribute.
            response = table.update_item(
                Key=payload['key'],
                UpdateExpression=payload['update_expression'],
                ConditionExpression=payload['condition_expression'],
                ExpressionAttributeValues=payload.get('expression_attribute_values'),
                ExpressionAttributeNames=payload.get('expression_attribute_names'),
                ReturnValues="ALL_NEW"
            )
            return {"success": True, "attributes": response.get('Attributes', {})}
        except ClientError as e:
            if e.response['Error']['Code'] == 'ConditionalCheckFailedException':
                return {"success": False, "error": "Conditional check failed"}
            else:
                raise e
    result = execute_update()
    return result

import os
import assemblyai as aai
from typing import Dict, Any


def initialize_transcriber() -> aai.Transcriber:
    """Initialize the AssemblyAI transcriber with API key from environment."""
    api_key = os.getenv("ASSEMBLYAI_API_KEY")
    if not api_key:
        raise ValueError("ASSEMBLYAI_API_KEY environment variable not set")

    aai.settings.api_key = api_key
    return aai.Transcriber()


def transcribe_audio(audio_url: str = None, audio_file: str = None) -> Dict[str, Any]:
    """Transcribe synthesized QA samples to verify spoken output using AssemblyAI."""
    transcriber = initialize_transcriber()

    config = aai.TranscriptionConfig()

    if audio_url:
        transcript = transcriber.transcribe(audio_url, config)
    elif audio_file:
        transcript = transcriber.transcribe(audio_file, config)
    else:
        raise ValueError("Either audio_url or audio_file must be provided")

    if transcript.status == aai.TranscriptStatus.error:
        raise RuntimeError(f"Transcription failed: {transcript.error}")

    return {
        "text": transcript.text,
        "words": [
            {"text": word.text, "start": word.start, "end": word.end}
            for word in transcript.words
        ],
        "confidence": transcript.confidence,
    }

