import base64
from typing import Union

import boto3
from botocore.exceptions import BotoCoreError, ClientError


class KMSKeyManager:
    def __init__(self, key_id: str, region_name: str = None):
        self.key_id = key_id
        self.kms = boto3.client("kms", region_name=region_name)

    def encrypt(self, plaintext: Union[str, bytes]) -> str:
        if isinstance(plaintext, str):
            plaintext = plaintext.encode("utf-8")

        try:
            response = self.kms.encrypt(KeyId=self.key_id, Plaintext=plaintext)
        except (BotoCoreError, ClientError) as e:
            raise RuntimeError(f"AWS KMS encrypt failed: {e}") from e

        ciphertext_blob = response["CiphertextBlob"]
        return base64.b64encode(ciphertext_blob).decode("utf-8")

    def decrypt(self, ciphertext_b64: str) -> str:
        ciphertext_blob = base64.b64decode(ciphertext_b64.encode("utf-8"))

        try:
            response = self.kms.decrypt(CiphertextBlob=ciphertext_blob)
        except (BotoCoreError, ClientError) as e:
            raise RuntimeError(f"AWS KMS decrypt failed: {e}") from e

        plaintext = response["Plaintext"]
        return plaintext.decode("utf-8")

    def sign(self, message: Union[str, bytes], signing_algorithm: str = "RSASSA_PSS_SHA_256") -> str:
        if isinstance(message, str):
            message = message.encode("utf-8")

        try:
            response = self.kms.sign(
                KeyId=self.key_id,
                Message=message,
                MessageType="RAW",
                SigningAlgorithm=signing_algorithm,
            )
        except (BotoCoreError, ClientError) as e:
            raise RuntimeError(f"AWS KMS sign failed: {e}") from e

        return base64.b64encode(response["Signature"]).decode("utf-8")

    def verify(
        self,
        message: Union[str, bytes],
        signature_b64: str,
        signing_algorithm: str = "RSASSA_PSS_SHA_256",
    ) -> bool:
        if isinstance(message, str):
            message = message.encode("utf-8")

        signature = base64.b64decode(signature_b64.encode("utf-8"))

        try:
            response = self.kms.verify(
                KeyId=self.key_id,
                Message=message,
                MessageType="RAW",
                Signature=signature,
                SigningAlgorithm=signing_algorithm,
            )
        except (BotoCoreError, ClientError) as e:
            raise RuntimeError(f"AWS KMS verify failed: {e}") from e

        return bool(response.get("SignatureValid", False))

