from google.cloud import texttospeech

def select_voice(payload, config=None):
    config = config or {}
    client = texttospeech.TextToSpeechClient()
    # Expects a payload like {"locale": "en-AU"}
    target_locale = payload.get("locale", "en-US")
    response_voices = client.list_voices(language_code=target_locale).voices

    selected_voice = None
    # Prefer a standard voice (not WaveNet) for predictability
    for voice in response_voices:
        if "Standard" in voice.name:
            selected_voice = voice
            break

    # Fallback to the first available voice if no standard one is found
    if not selected_voice and response_voices:
        selected_voice = response_voices[0]
    result = {"name": selected_voice.name} if selected_voice else None
    return result

