import os
from typing import Iterable, List, Sequence

from openai import OpenAI


DEFAULT_EMBED_MODEL = os.getenv("OPENAI_EMBEDDING_MODEL", "text-embedding-3-small")


def _normalize_texts(items: Iterable[str]) -> List[str]:
    texts = []
    for item in items:
        if item is None:
            continue
        text = str(item).strip()
        if text:
            texts.append(text)
    return texts


def embed_query_and_documents(
    query: str,
    documents: Sequence[str],
    model: str = DEFAULT_EMBED_MODEL,
):
    client = OpenAI(api_key=os.getenv("OPENAI_API_KEY"))

    query_text = str(query).strip()
    if not query_text:
        raise ValueError("query must be a non-empty string")

    docs = _normalize_texts(documents)
    if not docs:
        raise ValueError("documents must contain at least one non-empty string")

    query_response = client.embeddings.create(
        model=model,
        input=query_text,
    )
    document_response = client.embeddings.create(
        model=model,
        input=docs,
    )

    query_embedding = query_response.data[0].embedding
    document_embeddings = [item.embedding for item in document_response.data]

    return {
        "model": model,
        "query": query_embedding,
        "documents": document_embeddings,
    }

