import os
import requests

def stream_chunks(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.environ["DEEPGRAM_API_KEY"]
    audio_bytes = bytearray()
    if hasattr(payload, "__aiter__"):
        import asyncio

        async def _collect():
            async for chunk in payload:
                if chunk:
                    audio_bytes.extend(chunk)

        asyncio.run(_collect())
    else:
        for chunk in payload:
            if chunk:
                audio_bytes.extend(chunk)

    headers = {
        "Authorization": f"Token {api_key}",
        "Content-Type": config.get("content_type", "audio/wav"),
    }
    params = {
        "model": config.get("model", "nova-2"),
        "smart_format": str(config.get("smart_format", True)).lower(),
        "language": config.get("language", "en-US"),
    }
    response = requests.post(
        "https://api.deepgram.com/v1/listen",
        headers=headers,
        params=params,
        data=bytes(audio_bytes),
        timeout=config.get("timeout", 300),
    )
    response.raise_for_status()
    data = response.json()
    result = (
