# translate_dictionary_values.py – translates dictionary values while preserving keys
# Uses DeepL API (concrete provider)
import os
import requests
from typing import Dict, Any

# Provider-specific signal
DEEPL_AUTH_KEY = os.getenv('DEEPL_AUTH_KEY')

def _deepL_translate(text: str, target_lang: str = 'EN') -> str:
    url = 'https://api.deepl.com/v2/translate'
    params = {
        'auth_key': DEEPL_AUTH_KEY,
        'text': text,
        'target_lang': target_lang,
    }
    resp = requests.post(url, data=params)
    resp.raise_for_status()
    data = resp.json()
    return data['translations'][0]['text']

def translate_dictionary_values(data: Dict[str, Any], target_lang: str = 'EN') -> Dict[str, Any]:
    """Recursively translate all string values in a dictionary, preserving keys.
    Non‑string values are left unchanged. If a value is a list, each string element is
    translated.

    Args:
        data: Input dictionary containing string values to translate.
        target_lang: Target language code (default 'EN').

    Returns:
        New dictionary with translated string values.
    """
    def _walk(obj: Any) -> Any:
        if isinstance(obj, str):
            return _deepL_translate(obj, target_lang)
        elif isinstance(obj, dict):
            return {k: _walk(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_walk(item) for item in obj]
        else:
            return obj
    return _walk(data)

# Example usage
if __name__ == '__main__':
    sample = {
        'welcome': 'Bienvenue',
        'farewell': 'Au revoir',
        'details': {
            'greeting': 'Bonjour',
            'note': 'Merci beaucoup',
        },
        'items': ['Ceci', 'est', 'un', 'test']
    }
    translated = translate_dictionary_values(sample, target_lang='EN')
    print(translated)

