HEADERS = {
    'Authorization': f'Bearer {GOOGLE_API_KEY}',
    'Content-Type': 'application/json',
}

def embed_translated_segments(segments: List[str]) -> List[Dict[str, Any]]:
    """Generate embeddings for a list of translated text segments.

    Returns a list of dicts with:
        * 'text': original segment
        * 'embedding': list of float values (embedding vector)
    """
    payload = {
        'inputs': [{'text': seg} for seg in segments],
        'model': 'models/embed-text-001',  # concrete model identifier
        'parameters': {
            'dimensions': 1536,
        },
    }
    resp = requests.post(f"{BASE_URL}/embeddings:generate", headers=HEADERS, json=payload)
    resp.raise_for_status()
    data = resp.json()
    # Expected format: { 'embeddings': [{ 'text': ..., 'embedding': [...]} ] }
    embeddings = []
    for entry in data.get('embeddings', []):
        embeddings.append({
            'text': entry.get('text'),
            'embedding': entry.get('embedding'),
        })
    return embeddings

# Example usage
if __name__ == '__main__':
    sample_segments = [
        'Bonjour le monde!',
        'How are you?',
        'El mundo es hermoso.',
    ]
