    prod_example = {"id": "demo", "msg": "hello"}
    produce(prod, "my-events", json.dumps(prod_example))

    # Demo consumer usage
    cons = create_consumer()
    msg = consume_once(cons, "my-events")
    print("Consumed:", msg)

    # Cleanup
    prod.close()
    cons.close()

