import os
from google.cloud import documentai
from google.api_core.client_options import ClientOptions

def normalize_expense(payload, config=None):
    config = config or {}
    # Config should contain: project_id, location, processor_id, mime_type
    # Example config:
    # {
    #   "project_id": "your-gcp-project-id",
    #   "location": "us",
    #   "processor_id": "your-processor-id", # e.g., a pre-built "EXPENSE_PROCESSOR"
    #   "mime_type": "application/pdf"
    # }
    location = config.get("location", "us")
    opts = ClientOptions(api_endpoint=f"{location}-documentai.googleapis.com")

    client = documentai.DocumentProcessorServiceClient(client_options=opts)

    name = client.processor_path(
        config["project_id"], config["location"], config["processor_id"]
    )

    raw_document = documentai.RawDocument(
        content=payload, mime_type=config["mime_type"]
    )

    request = documentai.ProcessRequest(name=name, raw_document=raw_document)

    response = client.process_document(request=request)
    document = response.document

    normalized_data = {}
    for entity in document.entities:
        key = entity.type_

        # Handle line items, which are structured as nested entities
        if key == "line_item":
            if "line_items" not in normalized_data:
                normalized_data["line_items"] = []

            line_item_data = {}
            for prop in entity.properties:
                # For simplicity, using mention_text. Could be further normalized.
                line_item_data[prop.type_] = prop.mention_text
            normalized_data["line_items"].append(line_item_data)
            continue

        # Extract normalized value if available, otherwise use raw text
        if entity.normalized_value:
            if hasattr(entity.normalized_value, "money_value") and entity.normalized_value.money_value:
                value = {
                    "amount": float(f"{entity.normalized_value.money_value.units}.{abs(entity.normalized_value.money_value.nanos):09d}"),
                    "currency": entity.normalized_value.money_value.currency_code,
                }
            elif hasattr(entity.normalized_value, "date_value") and entity.normalized_value.date_value:
                date = entity.normalized_value.date_value
                value = f"{date.year}-{date.month:02d}-{date.day:02d}"
            else:
                value = entity.normalized_value.text
        else:
            value = entity.mention_text

        normalized_data[key] = value

    result = normalized_data
    return result

